import data from "./generated.json";
import { howToRoles, type HowToRole } from "@/content/site/howto";

/** Generated by scripts/build-howto.py from the approved How to Use page. */
export type HowToSection = {
  role: HowToRole;
  slug: string; // "" for the role landing (Start here)
  html: string;
  toc: { id: string; label: string }[];
  text: string;
};

const sections = data as Record<string, HowToSection>;

export const startSection = (role: HowToRole) =>
  Object.values(sections).find((s) => s.role === role && s.slug === "")!;

export const guideSection = (role: HowToRole, slug: string) => {
  const g = howToRoles[role].guides.find((x) => x.slug === slug);
  return g ? sections[g.sourceId] : undefined;
};

/** FAQ pairs from a guide's <details> blocks, for FAQPage structured data. */
export const faqsFromHtml = (html: string) =>
  [...html.matchAll(/<summary>([\s\S]*?)<\/summary>\s*<p>([\s\S]*?)<\/p>/g)].map((m) => ({
    q: m[1].replace(/<[^>]+>/g, "").trim(),
    a: m[2].replace(/<[^>]+>/g, "").replace(/\s+/g, " ").trim(),
  }));

/** Small search index for the hub: one row per guide. */
export const searchIndex = () =>
  (Object.keys(howToRoles) as HowToRole[]).flatMap((role) => [
    { role, label: howToRoles[role].label, title: "Start here", href: `/how-to-use/${role}`, text: startSection(role).text.slice(0, 600) },
    ...howToRoles[role].guides.map((g) => ({
      role,
      label: howToRoles[role].label,
      title: g.title,
      href: `/how-to-use/${role}/${g.slug}`,
      text: (sections[g.sourceId]?.text ?? "").slice(0, 1500),
    })),
  ]);
